values.content:
=You are a senior sales coach. Analyze this sales objection and provide a strategic response.

Context:
- Product/Service: {{ $json.body.product || 'Not specified' }}
- Prospect Industry: {{ $json.body.industry || 'Not specified' }}
- Sales Stage: {{ $json.body.stage || 'Not specified' }}

Return JSON:
{
  "objection_category": "price/timing/competition/authority/need/trust",
  "objection_severity": "high/medium/low",
  "root_cause": "underlying reason for objection",
  "recommended_response": "full response script the rep should use",
  "follow_up_questions": ["probing questions to ask"],
  "do_not_say": ["phrases to avoid"],
  "success_probability": 75,
  "alternative_approaches": ["other strategies to try"]
}

Objection:
{{ $json.body.objection_text }}

parameters.jsCode:
const items = $input.all();
const aiResponse = items[0].json.message.content;
let parsed;
try {
  parsed = JSON.parse(aiResponse);
} catch(e) {
  parsed = { objection_category: 'unknown', recommended_response: aiResponse, success_probability: 0 };
}
return [{
  json: {
    date: new Date().toISOString().split('T')[0],
    objectionText: items[0].json.body?.objection_text || '',
    product: items[0].json.body?.product || '',
    category: parsed.objection_category || '',
    severity: parsed.objection_severity || '',
    rootCause: parsed.root_cause || '',
    response: parsed.recommended_response || '',
    followUpQuestions: Array.isArray(parsed.follow_up_questions) ? parsed.follow_up_questions.join('\n') : '',
    doNotSay: Array.isArray(parsed.do_not_say) ? parsed.do_not_say.join('; ') : '',
    successProbability: parsed.success_probability || 0,
    alternatives: Array.isArray(parsed.alternative_approaches) ? parsed.alternative_approaches.join('\n') : '',
    salesRep: items[0].json.body?.sales_rep || ''
  }
}];
